const database=process.argv[2],directory=process.argv[3];assert.match(database??'',/^whole_trip_[a-z0-9_]+$/);assert.match(path.basename(directory??''),/^alzhen-planned-routes-[a-f0-9]+$/);
function query(sql){return new Promise((resolve,reject)=>{const child=spawn('C:/Program Files/PostgreSQL/18/bin/psql.exe',['-w','-h','127.0.0.1','-p','55443','-U','fixture','-d',database,'-At','-v','ON_ERROR_STOP=1','-c',sql],{windowsHide:true});let out='',err='';child.stdout.on('data',v=>out+=v);child.stderr.on('data',v=>err+=v);child.on('error',reject);child.on('close',code=>code?reject(Error(err)):resolve(out.trim()));});}
(async()=>{assert.equal(path.normalize(await query('SHOW data_directory')).toLowerCase(),path.normalize(directory).toLowerCase());const trip='00000000-0000-4000-8000-000000000080';await query(`INSERT INTO trips VALUES('${trip}');INSERT INTO trip_stops(id,trip_id) VALUES('00000000-0000-4000-8000-000000000081','${trip}'),('00000000-0000-4000-8000-000000000082','${trip}');`);const sql=`SELECT jsonb_array_length(delete_whole_trips_v1(ARRAY['${trip}'::uuid],'00000000-0000-4000-8000-000000000001'))`;const result=await Promise.all([query(`BEGIN;${sql};SELECT pg_sleep(0.5);COMMIT;`),query(sql)]);assert.equal(result.filter(v=>v.split(/\r?\n/).includes('2')).length,2);assert.equal(await query(`SELECT count(*) FROM transaction_deletion_jobs WHERE trip_id='${trip}'`),'2');console.log(JSON.stringify({disposable:true,concurrentClients:2,identicalAcknowledgements:2,deleteJobs:2,duplicateDatabaseDeletion:false}));})().catch(e=>{console.error(e.message);process.exitCode=1;});
